def prompt(self):
    sid = self.req("session/new", {"cwd": os.getcwd(), "mcpServers": []})["result"]["sessionId"]
    t0 = time.perf_counter(); first = None; text = ""
    i = self.send("session/prompt", {"sessionId": sid, "prompt": [{"type": "text", "text": PROMPT}]})
    while True:
        d = self.read()
        if d.get("method") == "session/update":
            u = d["params"].get("update", {})
            if u.get("sessionUpdate") == "agent_message_chunk":
                t = (u.get("content") or {}).get("text", "")
                if t.strip() and first is None:
                    first = time.perf_counter() - t0
                text += t
        elif d.get("id") == i:
            break
    return {"mode": "warm", "ttft_s": first, "total_s": time.perf_counter() - t0, "text": text[:200],
            "correct": EXPECT in text}

